        .dark .default-avatar {
            background: linear-gradient(135deg, #4a5568 0%, #2d3748 100%);
        }

        /* 深色模式切换按钮 */
        .theme-toggle {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: none;
            background: #f5f5f5;
            color: #666;
            font-size: 16px;
            cursor: pointer;
