function exploreSearch() {
  let {java,source} = this;
  var key = this.getVariable('搜索关键词');
  var tab = this.getVariable('发现页类型') || '小说';
  var sources = this.getVariable('发现页来源') || '全部';
  if (!key) {
    try { java.toast('请输入搜索关键词'); } catch (e) {}
    return;
  }
  if (['t:', 'x:', 'd:', 'm:', 't：', 'x：', 'd：', 'm：'].some(p => key.startsWith(p))) {
  tab = '';
}
if(key.includes('@')) {
	sources="";
	} else {
		sources = `@${sources}`
		}
  var tabMap = {
  	'小说':'x:',
  	'漫画':'m:',
  	'听书':'t:',
  	'短剧':'d:',
  	'':''
  	}
  key = `${tabMap[tab]}${key}${sources}`;
  try {
    java.searchBook(key, source);
  } catch (e1) {
    try { java.open('search', key); } catch (e2) { try { java.toast('搜索失败'); } catch (e3) {} }
  }
  java.refreshExplore();
}

