            border-radius: 8px;
            margin-bottom: 10px;
            cursor: pointer;
        }

        .comment-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .comment-meta {
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .comment-time {
            font-size: 12px;
            color: #999;
        }

        .comment-reply-btn {
