        }

        /* 展开回复 */
        .expand-replies {
            display: flex;
            align-items: center;
            margin-top: 12px;
            padding-left: 52px;
            color: #576b95;
            font-size: 13px;
            cursor: pointer;
        }

        .expand-replies::before {
            content: '';
            width: 20px;
            height: 1px;
            background: #ddd;
            margin-right: 8px;
        }

        .expand-replies i {
            margin-left: 4px;
            font-size: 10px;
            transition: transform 0.3s;
        }

        .expand-replies.expanded i {
            transform: rotate(180deg);
        }

        /* 回复列表 */
        .reply-list {
            margin-top: 12px;
            padding-left: 52px;
            display: none;
        }

        .reply-list.show {
            display: block;
        }

        .reply-item {
            padding: 12px 0;
            border-bottom: 1px solid #f5f5f5;
        }

        .reply-item:last-child {
            border-bottom: none;
        }

        .reply-main {
            display: flex;
            gap: 10px;
        }

        .reply-avatar img {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            object-fit: cover;
            background: #f0f0f0;
        }

        .reply-body {
            flex: 1;
            min-width: 0;
        }

        .reply-header {
            display: flex;
            align-items: center;
            flex-wrap: wrap;
            margin-bottom: 4px;
        }

        .reply-username {
            font-size: 13px;
            font-weight: 500;
            color: #333;
        }

        .reply-to {
            font-size: 13px;
            color: #999;
            margin: 0 4px;
        }

        .reply-to-username {
            font-size: 13px;
            color: #576b95;
        }

        .reply-content {
            font-size: 14px;
            color: #333;
            line-height: 1.5;
            margin-bottom: 6px;
        }

        .reply-content .bq {
            width: 18px;
            height: 18px;
            vertical-align: middle;
            margin: 0 1px;
        }

        .reply-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .reply-time {
            font-size: 11px;
            color: #999;
        }

        .reply-likes {
            display: flex;
            align-items: center;
            gap: 3px;
            color: #999;
            font-size: 12px;
        }

        /* 默认头像 */
        .default-avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
